// @vitest-environment node
//
// Cross-language drift guard for the CLUB-ENGINE mirrors (normalization item
// 2), run against catalog-platform/data/club-fixtures.json — the shared
// contract tests/test_club_fixtures.py also runs against
// app/club_announcements.py's Python mirrors.
//
// memberSchedulePosition/scheduleStatus/hasSchedule/tallyRatings/
// tallyPollVotes in THIS file are the CANON: site/club-reads.js is what the
// live browser app runs. This test verifies the fixture file (generated by
// executing these exact functions) is still what these functions produce —
// so a future edit to club-reads.js that silently changes behaviour fails
// HERE first, and the Python side's separate test tells you whether the
// mirror kept up.
//
// No sync step exists in this repo — read straight off the sibling
// checkout, same SKIP-not-fail posture as the Python side when
// catalog-platform is not found next to this repo.
import { describe, it, expect } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { memberSchedulePosition, scheduleStatus, hasSchedule, tallyRatings, tallyPollVotes } from '../club-reads.js';

const ENV_VAR = 'CATALOG_PLATFORM_DIR';
const CANDIDATES = ['../catalog-platform', '../../catalog-platform', '../../../catalog-platform'];

function findPlatformDir() {
  const fromEnv = process.env[ENV_VAR];
  if (fromEnv) {
    const dir = resolve(fromEnv);
    return existsSync(resolve(dir, 'data', 'club-fixtures.json')) ? dir : null;
  }
  for (const rel of CANDIDATES) {
    const dir = resolve(rel);
    if (existsSync(resolve(dir, 'data', 'club-fixtures.json'))) return dir;
  }
  return null;
}

const platformDir = findPlatformDir();
const describeOrSkip = platformDir ? describe : describe.skip;

describeOrSkip('club fixtures (site/club-reads.js is canon)', () => {
  // Read lazily: describe.skip still runs this factory to collect skipped
  // children (vitest 4), so an unconditional read here throws resolve(null,...)
  // when the sibling checkout is absent — exactly the CI condition.
  const fixtures = platformDir
    ? JSON.parse(readFileSync(resolve(platformDir, 'data', 'club-fixtures.json'), 'utf8'))
    : null;

  it('has the expected schema version and is not truncated', () => {
    expect(fixtures.schemaVersion).toBe(1);
    const total =
      fixtures.positionCases.length + fixtures.statusCases.length + fixtures.ratingsCases.length + fixtures.pollCases.length;
    expect(total).toBeGreaterThanOrEqual(30);
  });

  it('every memberSchedulePosition case reproduces, including the two ADVERSARIAL ones', () => {
    for (const c of fixtures.positionCases) {
      const got = memberSchedulePosition(c.milestones, c.progress, c.chaptered);
      expect(got, `${c.name} — ${c.why || ''}`).toBe(c.expectPosition);
    }
  });

  it('every hasSchedule + scheduleStatus case reproduces', () => {
    for (const c of fixtures.statusCases) {
      expect(hasSchedule(c.milestones), c.name).toBe(c.expectHasSchedule);
      expect(scheduleStatus(c.milestones, c.progress, c.chaptered, c.nowMs), c.name).toEqual(c.expectStatus);
    }
  });

  it('every tallyRatings case reproduces', () => {
    for (const c of fixtures.ratingsCases) {
      expect(tallyRatings(c.ratings), c.name).toEqual(c.expect);
    }
  });

  it('every tallyPollVotes case reproduces', () => {
    for (const c of fixtures.pollCases) {
      expect(tallyPollVotes(c.options, c.votes), c.name).toEqual(c.expect);
    }
  });

  it('records the divergence this fixture caught: the two ADVERSARIAL position cases disagree with the OLD (pre-fix) Python inference', () => {
    // Documentary, not a Python call from JS — see club-fixtures.json's
    // _divergenceFound2026_08_14 and app/club_announcements.py's
    // member_position docstring for the fix. This just pins that the two
    // adversarial fixtures still produce the values that exposed the bug.
    const a = fixtures.positionCases.find((c) => c.name.startsWith('ADVERSARIAL: milestones carry chEnd but chaptered is explicitly false'));
    const b = fixtures.positionCases.find((c) => c.name.startsWith('ADVERSARIAL: milestones lack chEnd but chaptered is explicitly true'));
    expect(a.expectPosition).toBe(1);
    expect(b.expectPosition).toBe(-1);
  });
});

describe('club fixtures: skip reason is visible when the sibling checkout is absent', () => {
  it('is a no-op assertion so this file always reports at least one test', () => {
    if (!platformDir) {
      // eslint-disable-next-line no-console
      console.warn(`catalog-platform not found (tried ${ENV_VAR} and ${CANDIDATES.join(', ')}); club fixtures skipped.`);
    }
    expect(true).toBe(true);
  });
});
